def _process(self, sym, resolved_scales):
    """Recursively replace Sqrt/Power with RegPower where a scale is registered."""
    if not sym.children:
        return sym

    new_children = [self._process(child, resolved_scales) for child in sym.children]

    if isinstance(sym, pybamm.Sqrt):
        scale = self._get_scale(new_children[0], resolved_scales)
        if scale is not None:
            return pybamm.RegPower(new_children[0], 0.5, scale=scale)

    elif isinstance(sym, pybamm.Power):
        scale = self._get_scale(new_children[0], resolved_scales)
        if scale is not None:
            return pybamm.RegPower(new_children[0], new_children[1], scale=scale)

    if any(n is not o for n, o in zip(new_children, sym.children, strict=True)):
        return sym.create_copy(new_children=new_children)
    return sym

