def _get_scale(self, expr, resolved_scales):
    """Get the registered scale for an expression, or None if unregistered.

    Only exact matches are used. For patterns like (c_max - c_s),
    they must be explicitly registered in the scales dict. A return value
    of None means the power must be left unregularised.
    """
    for var, scale in resolved_scales.items():
        if expr == var:
            return scale
    return None
